from taf.gnb.oam.coam.admin.exceptions import raise_value_error


class CplaneCuTrace(object):
    def __init__(self, dscp, collector_destination_ip, collector_destination_port):

        self.dscp = self.validate_param('dscp', dscp, 0 <= dscp <= 63)
        self.collector_destination_ip = collector_destination_ip
        self.collector_destination_port = self.validate_param('collectorDestinationPort',
                                                              collector_destination_port,
                                                              1024 <= collector_destination_port <= 65535)

    def as_dict(self):
        attributes = {
            "dscp": self.dscp,
            "collectorDestinationIp": self.collector_destination_ip,
            "collectorDestinationPort": self.collector_destination_port
        }
        return attributes

    @staticmethod
    def validate_param(param, value, valid):
        return value if valid else raise_value_error(
            param=param,
            value=str(value),
            subpage="tutorial-startCPlaneCUTrace.html")
